#!/bin/bash
# cloud-agent setup — generated by build-setup.sh from github.com/ericz218/cloud-agent (do not edit by hand).
# Paste into: claude.ai/code → environment menu → Edit → Setup script.
# Installs OpenCode (BYOK coding agent), the oc-agent wrapper and relay instructions.
# Optional argument: a profile name (see profiles/), e.g. "... | bash -s muse", which sets
# non-secret defaults (base URL, models) so only BYOK_API_KEY has to be set per account.
set -euo pipefail
PROFILE="${1:-}"
if ! command -v opencode >/dev/null || [ "$(opencode --version 2>/dev/null)" != "1.19.4" ]; then
  npm install -g --no-fund --no-audit "opencode-ai@1.19.4"
fi

install -d "/opt/cloud-agent"
cat > "/opt/cloud-agent/gen-opencode-config.sh" <<'__CLOUD_AGENT_EOF__'
#!/usr/bin/env bash
# Writes the OpenCode config from BYOK_* env vars. The API key itself never lands
# on disk: the config references it as {env:BYOK_API_KEY}.
#
#   BYOK_PROVIDER   anthropic | openai | openrouter | openai-compatible (default)
#   BYOK_BASE_URL   API base URL (optional for anthropic/openai/openrouter)
#   BYOK_API_KEY    API key (secret, read at request time)
#   BYOK_MODEL      model ID sent to the API, e.g. claude-sonnet-4-5, gpt-5, deepseek/deepseek-chat
#   BYOK_SMALL_MODEL   optional cheaper model for titles/summaries (defaults to BYOK_MODEL)
#   BYOK_EXTRA_MODELS  optional comma-separated extra model IDs selectable in the UI
#   BYOK_SUBAGENT_MODEL  optional model ID for general/explore agents (falls back to first 'contributor' in BYOK_EXTRA_MODELS; unset = no agent override)
#   BYOK_REASONING_EFFORT  optional reasoning level sent with every request, e.g. low | medium | high | xhigh | max
#                      (openai / openrouter / openai-compatible; ignored for anthropic)
set -euo pipefail

out="${1:?usage: gen-opencode-config.sh <output.json>}"
provider="${BYOK_PROVIDER:-openai-compatible}"
model="${BYOK_MODEL:?BYOK_MODEL is required}"
small="${BYOK_SMALL_MODEL:-$model}"

case "$provider" in
  anthropic)  npm="@ai-sdk/anthropic";           default_url="https://api.anthropic.com/v1" ;;
  openai)     npm="@ai-sdk/openai";              default_url="https://api.openai.com/v1" ;;
  openrouter) npm="@openrouter/ai-sdk-provider"; default_url="https://openrouter.ai/api/v1" ;;
  openai-compatible|compatible|custom)
              npm="@ai-sdk/openai-compatible";   default_url="" ;;
  *) echo "gen-opencode-config: unknown BYOK_PROVIDER '$provider'" >&2; exit 1 ;;
esac
base_url="${BYOK_BASE_URL:-$default_url}"
[ -n "$base_url" ] || { echo "gen-opencode-config: BYOK_BASE_URL is required for $provider" >&2; exit 1; }

subagent_model="${BYOK_SUBAGENT_MODEL:-}"
if [ -z "$subagent_model" ] && [ -n "${BYOK_EXTRA_MODELS:-}" ]; then
  subagent_model="$(jq -rn --arg csv "$BYOK_EXTRA_MODELS" \
    '[$csv | split(",")[] | gsub("^\\s+|\\s+$"; "") | select(length > 0) | select(ascii_downcase | contains("contributor"))][0] // empty')"
fi

models_csv="$model,$small${BYOK_EXTRA_MODELS:+,$BYOK_EXTRA_MODELS}"

effort="${BYOK_REASONING_EFFORT:-}"
model_options='{}'
if [ -n "$effort" ]; then
  case "$provider" in
    anthropic)  echo "gen-opencode-config: BYOK_REASONING_EFFORT is ignored for anthropic" >&2 ;;
    openrouter) model_options="$(jq -nc --arg e "$effort" '{reasoning: {effort: $e}}')" ;;
    *)          model_options="$(jq -nc --arg e "$effort" '{reasoningEffort: $e}')" ;;
  esac
fi

render_mcp_enabled=false
[ -n "${RENDER_API_KEY:-}" ] && render_mcp_enabled=true

mkdir -p "$(dirname "$out")"
jq -n \
  --arg npm "$npm" --arg kind "$provider" --arg url "$base_url" \
  --arg model "$model" --arg small "$small" --arg models "$models_csv" \
  --arg subagent "$subagent_model" \
  --argjson render "$render_mcp_enabled" --argjson mopts "$model_options" \
  '{
    "$schema": "https://opencode.ai/config.json",
    autoupdate: false,
    share: "disabled",
    enabled_providers: ["byok"],
    model: ("byok/" + $model),
    small_model: ("byok/" + $small),
    provider: {
      byok: {
        npm: $npm,
        name: ("BYOK (" + $kind + ")"),
        options: { baseURL: $url, apiKey: "{env:BYOK_API_KEY}" },
        models: ($models | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))
                 | unique | map({key: ., value: ({name: .} + (if $mopts == {} then {} else {options: $mopts} end))}) | from_entries)
      }
    },
    permission: {
      edit: "allow",
      external_directory: "allow",
      webfetch: "allow",
      bash: { "*": "allow", "git push --force*": "deny", "git push -f*": "deny", "git push * --force*": "deny", "rm -rf /*": "deny" }
    },
    mcp: {
      render: {
        type: "remote",
        url: "https://mcp.render.com/mcp",
        headers: { Authorization: "Bearer {env:RENDER_API_KEY}" },
        enabled: $render
      }
    }
  }' > "$out"

# Merge sub-agent model override + AGENTS.md instructions into any existing
# config (preserving unknown/user fields); create a minimal config if needed.
cfg_dir="$(dirname "$out")"
agents_md="$cfg_dir/AGENTS.md"
if [ -n "$subagent_model" ]; then
  case "$subagent_model" in byok/*) subagent_ref="$subagent_model" ;; *) subagent_ref="byok/$subagent_model" ;; esac
else
  subagent_ref=""
fi
SUBAGENT_REF="$subagent_ref" AGENTS_MD="$agents_md" python3 - "$out" <<'PYEOF'
import json, os, sys

path = sys.argv[1]
subagent = os.environ.get("SUBAGENT_REF", "")
agents_md = os.environ.get("AGENTS_MD", "")

try:
    with open(path, encoding="utf-8") as f:
        cfg = json.load(f)
    if not isinstance(cfg, dict):
        cfg = {}
except (FileNotFoundError, json.JSONDecodeError, OSError):
    # Config just rendered above (or missing): re-read if possible, else start empty.
    cfg = {}
    if os.path.exists(path):
        try:
            with open(path, encoding="utf-8") as f:
                cfg = json.load(f)
            if not isinstance(cfg, dict):
                cfg = {}
        except (json.JSONDecodeError, OSError):
            cfg = {}

if subagent:
    agent = cfg.get("agent")
    if not isinstance(agent, dict):
        agent = {}
    for name in ("general", "explore"):
        entry = agent.get(name)
        if not isinstance(entry, dict):
            entry = {}
        entry["model"] = subagent
        agent[name] = entry
    cfg["agent"] = agent

if agents_md:
    instructions = cfg.get("instructions")
    if not isinstance(instructions, list):
        instructions = [instructions] if instructions else []
    if agents_md not in instructions:
        instructions.append(agents_md)
    cfg["instructions"] = instructions

tmp = path + ".tmp"
with open(tmp, "w", encoding="utf-8") as f:
    json.dump(cfg, f, indent=2, ensure_ascii=False)
    f.write("\n")
os.replace(tmp, path)
PYEOF
__CLOUD_AGENT_EOF__
chmod 755 "/opt/cloud-agent/gen-opencode-config.sh"

install -d "/usr/local/bin"
cat > "/usr/local/bin/oc-agent" <<'__CLOUD_AGENT_EOF__'
#!/usr/bin/env bash
# Run a coding task with the BYOK OpenCode agent and print a short result.
#
#   oc-agent [-c] [-m MODEL] [-e EFFORT] [-d DIR] "task description"
#     -c      continue the previous OpenCode session (follow-up instructions)
#     -m      model ID for this task (one of BYOK_MODEL / BYOK_SMALL_MODEL / BYOK_EXTRA_MODELS)
#     -e      reasoning effort for this task (low | medium | high | xhigh | max); default BYOK_REASONING_EFFORT
#     -d DIR  working directory (default: current directory)
#
# Model/API come from BYOK_PROVIDER, BYOK_BASE_URL, BYOK_MODEL, BYOK_API_KEY.
# The full transcript goes to /tmp/oc-agent/*.log; only its tail is printed so
# the calling (relay) model reads as little as possible.
set -uo pipefail

cont=() model=() pick="" dir="$PWD"
while getopts "cm:e:d:h" o; do
  case "$o" in
    c) cont=(--continue) ;;
    m) model=(--model "byok/$OPTARG"); pick="$OPTARG" ;;
    e) export BYOK_REASONING_EFFORT="$OPTARG" ;;
    d) dir="$OPTARG" ;;
    *) sed -n '2,12p' "$0"; exit 2 ;;
  esac
done
shift $((OPTIND - 1))
[ $# -gt 0 ] || { sed -n '2,12p' "$0"; exit 2; }

# Profile defaults (non-secret): the one chosen by `setup.sh <profile>`, else the
# profile whose BYOK_BASE_URL matches the configured one. Real env vars win.
profile=/opt/cloud-agent/profile.env
if [ ! -f "$profile" ] && [ -n "${BYOK_BASE_URL:-}" ]; then
  profile="$(grep -lxF "BYOK_BASE_URL=${BYOK_BASE_URL%/}" /opt/cloud-agent/profiles/*.env 2>/dev/null | head -n 1)"
fi
if [ -n "$profile" ] && [ -f "$profile" ]; then
  while IFS='=' read -r k v; do
    case "$k" in BYOK_*) [ -n "${!k:-}" ] || export "$k=$v" ;; esac
  done < <(grep -E '^[A-Z_]+=' "$profile")
fi

for v in BYOK_MODEL BYOK_API_KEY; do
  if [ -z "${!v:-}" ]; then
    echo "oc-agent: $v is not set. Add it under the cloud environment's settings → Environment variables, then start a new session." >&2
    exit 3
  fi
done

# A model picked with -m is always selectable, even if it is not in the configured lists.
[ -z "$pick" ] || export BYOK_EXTRA_MODELS="${BYOK_EXTRA_MODELS:+$BYOK_EXTRA_MODELS,}$pick"

# Meta's *-contributor models reject reasoning effort "max"; use the next level down.
if [ "${BYOK_REASONING_EFFORT:-}" = "max" ] && [[ "${model[1]:-byok/$BYOK_MODEL}" == *-contributor ]]; then
  echo "oc-agent: ${model[1]:-$BYOK_MODEL} does not support effort max, using xhigh" >&2
  export BYOK_REASONING_EFFORT=xhigh
fi

cfg="${XDG_CONFIG_HOME:-$HOME/.config}/opencode/opencode.json"
/opt/cloud-agent/gen-opencode-config.sh "$cfg" || exit 3

mkdir -p /tmp/oc-agent
log="/tmp/oc-agent/$(date +%Y%m%d-%H%M%S).log"
cd "$dir" || exit 2
echo "oc-agent: model=${model[1]:-byok/$BYOK_MODEL} effort=${BYOK_REASONING_EFFORT:-model-default} dir=$dir log=$log" >&2

# Startup can hang on OpenCode's background models.dev download (6 MB, no timeout) when the
# network is flaky. Our models are configured explicitly, so skip it. As a safety net, an
# attempt that hasn't started its agent loop within $OC_AGENT_START_TIMEOUT seconds is
# killed and retried.
export OPENCODE_DISABLE_MODELS_FETCH=1 OPENCODE_DISABLE_AUTOUPDATE=1
start_timeout="${OC_AGENT_START_TIMEOUT:-120}"
raw="$log.raw"
# Live view for oc-progress: the run currently (or most recently) in progress.
ln -sfn "$raw" /tmp/oc-agent/current.raw
printf '%s %s %s\n' "$$" "$(date +%s)" "${model[1]:-byok/$BYOK_MODEL}" > /tmp/oc-agent/current.info
rc=4
for attempt in 1 2 3; do
  # One stream so progress and tool steps stay in order; log lines are filtered out when shown.
  opencode run --print-logs --log-level INFO "${cont[@]}" "${model[@]}" "$*" >"$raw" 2>&1 </dev/null &
  pid=$!
  started=0
  for _ in $(seq 1 "$start_timeout"); do
    if grep -q 'message=loop' "$raw"; then started=1; break; fi
    kill -0 "$pid" 2>/dev/null || break
    sleep 1
  done
  if [ "$started" = 0 ] && kill -0 "$pid" 2>/dev/null; then
    kill "$pid" 2>/dev/null; sleep 2; kill -9 "$pid" 2>/dev/null; wait "$pid" 2>/dev/null
    echo "oc-agent: opencode did not start within ${start_timeout}s (attempt $attempt/3)" >&2
    continue
  fi
  wait "$pid"; rc=$?
  break
done
[ "$rc" != 4 ] || echo "oc-agent: opencode failed to start 3 times; see $raw" >&2
grep -v '^timestamp=' "$raw" | sed -r 's/\x1b\[[0-9;]*[A-Za-z]//g' > "$log"

echo "---- oc-agent exit=$rc, $(wc -l < "$log") log lines, last 80: ----"
tail -n 80 "$log"
exit "$rc"
__CLOUD_AGENT_EOF__
chmod 755 "/usr/local/bin/oc-agent"

install -d "/usr/local/bin"
cat > "/usr/local/bin/oc-progress" <<'__CLOUD_AGENT_EOF__'
#!/usr/bin/env bash
# Show what the BYOK agent (oc-agent) is doing right now: status plus the last
# N lines of its live output (default 40), with terminal colour codes removed.
#
#   oc-progress [N]
set -uo pipefail
n="${1:-40}"
info=/tmp/oc-agent/current.info
raw=/tmp/oc-agent/current.raw
if [ ! -e "$raw" ] || [ ! -f "$info" ]; then
  echo "oc-progress: no oc-agent run yet in this session"; exit 1
fi
read -r pid started model < "$info"
mins=$(( ($(date +%s) - started) / 60 ))
if kill -0 "$pid" 2>/dev/null; then state="running for ${mins} min"; else state="finished (started ${mins} min ago)"; fi
echo "oc-agent: $state, model $model, $(grep -vc '^timestamp=' "$raw") output lines"
echo "----"
grep -v '^timestamp=' "$raw" | tail -n "$n" | sed -r 's/\x1b\[[0-9;]*[A-Za-z]//g'
__CLOUD_AGENT_EOF__
chmod 755 "/usr/local/bin/oc-progress"

install -d "/usr/local/bin"
cat > "/usr/local/bin/render-deploy-check" <<'__CLOUD_AGENT_EOF__'
#!/usr/bin/env bash
# Find the Render services built from a GitHub repo and report (or wait for)
# the deploy of a given commit, with logs when it fails.
#
#   render-deploy-check [--repo owner/name] [--branch BRANCH] [--sha SHA]
#                       [--service NAME_OR_ID] [--wait] [--timeout SECONDS] [--logs N]
#
# Defaults come from the git repo in the current directory: origin remote,
# current branch, HEAD sha. Exit codes: 0 live on the requested sha,
# 1 deploy failed, 2 timed out / not deployed yet, 3 usage or lookup error.
set -euo pipefail

API="https://api.render.com/v1"
repo="" branch="" sha="" service="" wait=0 timeout=900 nlogs=60
while [ $# -gt 0 ]; do
  case "$1" in
    --repo) repo="$2"; shift 2 ;;
    --branch) branch="$2"; shift 2 ;;
    --sha) sha="$2"; shift 2 ;;
    --service) service="$2"; shift 2 ;;
    --wait) wait=1; shift ;;
    --timeout) timeout="$2"; shift 2 ;;
    --logs) nlogs="$2"; shift 2 ;;
    -h|--help) sed -n '2,11p' "$0"; exit 0 ;;
    *) echo "unknown argument: $1" >&2; exit 3 ;;
  esac
done
[ -n "${RENDER_API_KEY:-}" ] || { echo "RENDER_API_KEY is not set" >&2; exit 3; }

if git rev-parse --git-dir >/dev/null 2>&1; then
  if [ -z "$repo" ]; then
    url="$(git remote get-url origin 2>/dev/null || true)"
    repo="$(sed -E 's#(git@github.com:|https://github.com/)##; s#\.git$##' <<<"$url")"
  fi
  [ -n "$branch" ] || branch="$(git branch --show-current)"
  [ -n "$sha" ] || sha="$(git rev-parse HEAD)"
fi

api() { curl -fsS -H "Authorization: Bearer $RENDER_API_KEY" -H "Accept: application/json" "$API$1"; }

services="$(api "/services?limit=100" | jq -c '[.[].service]')"
if [ -n "$service" ]; then
  matches="$(jq -c --arg s "$service" '[.[] | select(.id == $s or .name == $s)]' <<<"$services")"
else
  [ -n "$repo" ] || { echo "no --repo/--service given and no git origin here" >&2; exit 3; }
  matches="$(jq -c --arg r "$repo" --arg b "$branch" '[.[] | select((.repo // "" | ascii_downcase | rtrimstr(".git")) == ("https://github.com/" + $r | ascii_downcase))
             | select($b == "" or .branch == $b)]' <<<"$services")"
fi
count="$(jq length <<<"$matches")"
if [ "$count" -eq 0 ]; then
  echo "No Render service found for repo=${repo:-?} branch=${branch:-any} service=${service:-?}."
  echo "Services in this account:"; jq -r '.[] | "  \(.name)  \(.id)  \(.repo // "-")@\(.branch // "-")"' <<<"$services"
  exit 3
fi

terminal='^(live|deactivated|build_failed|update_failed|canceled|pre_deploy_failed)$'
rc=0
for row in $(jq -r '.[] | @base64' <<<"$matches"); do
  svc="$(base64 -d <<<"$row")"
  id="$(jq -r .id <<<"$svc")"; name="$(jq -r .name <<<"$svc")"; owner="$(jq -r .ownerId <<<"$svc")"
  echo "== $name ($id)  repo=$(jq -r '.repo // "-"' <<<"$svc")  branch=$(jq -r '.branch // "-"' <<<"$svc")"
  echo "   url=$(jq -r '.serviceDetails.url // "-"' <<<"$svc")  autoDeploy=$(jq -r .autoDeploy <<<"$svc")  suspended=$(jq -r .suspended <<<"$svc")"
  deadline=$(( $(date +%s) + timeout ))
  while :; do
    deploys="$(api "/services/$id/deploys?limit=10" | jq -c '[.[].deploy]')"
    if [ -n "$sha" ]; then
      dep="$(jq -c --arg s "$sha" '[.[] | select(.commit.id // "" | startswith($s))][0] // empty' <<<"$deploys")"
    else
      dep="$(jq -c '.[0] // empty' <<<"$deploys")"
    fi
    status="$(jq -r '.status // "none"' <<<"${dep:-{\}}")"
    if [ "$wait" -eq 0 ] || [[ "$status" =~ $terminal ]] || [ "$(date +%s)" -ge "$deadline" ]; then break; fi
    echo "   waiting: deploy for ${sha:0:7} is '$status'..."; sleep 15
  done
  live="$(jq -c '[.[] | select(.status == "live")][0] // empty' <<<"$deploys")"
  echo "   requested sha=${sha:-latest}  deploy=$(jq -r '.id // "-"' <<<"${dep:-{\}}")  status=$status"
  echo "   currently live: sha=$(jq -r '.commit.id // "-"' <<<"${live:-{\}}")  msg=$(jq -r '(.commit.message // "-") | split("\n")[0]' <<<"${live:-{\}}")  finished=$(jq -r '.finishedAt // "-"' <<<"${live:-{\}}")"
  case "$status" in
    live) [ -z "$sha" ] || [[ "$(jq -r '.commit.id' <<<"$live")" == "$sha"* ]] || { echo "   NOTE: requested deploy reported live but is not the current live deploy"; }; ;;
    build_failed|update_failed|pre_deploy_failed|canceled)
      rc=1; echo "   DEPLOY FAILED ($status). Last $nlogs build+app log lines:"
      api "/logs?ownerId=$owner&resource=$id&limit=$nlogs&direction=backward" \
        | jq -r '.logs | reverse | .[] | "   | \(.timestamp[11:19]) \(.labels | map(select(.name=="type"))[0].value // "") \(.message)"' || true ;;
    none) [ "$rc" -ne 0 ] || rc=2; echo "   no deploy found for this sha (autoDeploy off, or not pushed/started yet)";;
    *) [ "$rc" -ne 0 ] || rc=2; echo "   deploy still in progress or timed out ($status)";;
  esac
done
exit "$rc"
__CLOUD_AGENT_EOF__
chmod 755 "/usr/local/bin/render-deploy-check"

install -d "$HOME/.config/opencode"
cat > "$HOME/.config/opencode/AGENTS.md" <<'__CLOUD_AGENT_EOF__'
# Coding agent rules (Claude Code cloud session + OpenCode BYOK)

You are the coding agent, called the "主模型" (main model) in this environment: task text that says
the main model should do the work itself, or that no third-party layer / sub-agents may be used, means
you do the work directly without spawning sub-agents. A thin relay hands you tasks from a user who works from a phone and can't
see a terminal, so finish the work end to end and end with a short report.
For routine tasks, dispatch by default per the Task dispatch section below; do everything yourself only when the task text explicitly says the main model must do it personally / no sub-agents.

## Environment
- Ephemeral Linux container: anything not pushed to GitHub is lost when the session ends.
- Repos are cloned under `/home/user/<repo>`. Tools: git, gh, node/npm, python3/pip, curl, jq, rg,
  build-essential. Install anything else you need (npm/pip/apt).
- GitHub auth is handled transparently by the session (git and gh just work) but ONLY for repositories
  attached to this session. If git/gh says access is "not enabled for this session", stop and name the
  exact owner/repo that needs to be attached (the relay can attach it and continue you); don't try to
  work around it.
- Never print, echo, log or commit secrets or env var values (no `env`, `printenv`, `set`).

## Development loop
- GitHub is the source of truth: commit and push before you finish. Work on the branch the task names;
  otherwise on the current branch if it's a feature branch, else create one. Push to main only if the
  task says so.
- Install deps with the project's lockfile-respecting command (`npm ci`, `pnpm i --frozen-lockfile`, `uv sync`, ...).
- Run the project's build/tests/lint before committing; fix failures you caused.
- No force-push to main/master, no history rewrites, no deleting branches or repos.

## CI
After pushing: `gh run list --branch <b> -L 5`, wait with `gh run watch <id> --exit-status`;
on failure read `gh run view <id> --log-failed`, fix, push, watch again.

## Render
If `RENDER_API_KEY` is set, run `render-deploy-check --wait` inside the repo: it finds the Render
services built from this repo/branch, waits for the deploy of HEAD and prints status, live SHA and failure
logs (exit 0 = HEAD is live). Otherwise skip Render; the relay checks it.

## Report (last message, short)
Changed files (`git diff --stat`), branch, pushed commit SHA (full), test result, CI result, Render result
if checked, anything blocked.

## Task dispatch
- The 主模型 (you, the decision model running in oc-agent) is the decision model; it also directly executes a small number of high-difficulty tasks itself.
- On receiving a task, first split it and decide which parts to do yourself and which to dispatch to sub-agents; do not default to doing everything yourself.
- Dispatch independent small tasks to sub-agents (agent types `general` / `explore`) in parallel, with no concurrency limit; split work by file so multiple sub-agents never edit the same file.
- Sub-agents always use the contributor execution model (fixed in `opencode.json` under `agent.general` / `agent.explore`); never specify another model when dispatching.
- Pick the reasoning level dynamically by task difficulty: low for simple lookups / mechanical edits, medium for ordinary implementation, high for complex / security-related work; state the expected thinking depth explicitly in each sub-agent's task description.
- High-difficulty, security-sensitive, and cross-file design tasks are done by the 主模型 itself, not dispatched.
- The 主模型 independently reviews sub-agent results (read the diff, run tests) before submitting; never submit unreviewed results.
__CLOUD_AGENT_EOF__
chmod 644 "$HOME/.config/opencode/AGENTS.md"

# Merge sub-agent model override + AGENTS.md into instructions of the (possibly
# pre-existing / just-generated) opencode.json, preserving all other fields.
# Idempotent; prints no secrets (model names only).
cfg="${XDG_CONFIG_HOME:-$HOME/.config}/opencode/opencode.json"
agents_md="${XDG_CONFIG_HOME:-$HOME/.config}/opencode/AGENTS.md"
subagent_model="${BYOK_SUBAGENT_MODEL:-}"
if [ -z "$subagent_model" ] && [ -n "${BYOK_EXTRA_MODELS:-}" ]; then
  subagent_model="$(jq -rn --arg csv "$BYOK_EXTRA_MODELS" \
    '[$csv | split(",")[] | gsub("^\\s+|\\s+$"; "") | select(length > 0) | select(ascii_downcase | contains("contributor"))][0] // empty')"
fi
if [ -n "$subagent_model" ]; then
  case "$subagent_model" in byok/*) subagent_ref="$subagent_model" ;; *) subagent_ref="byok/$subagent_model" ;; esac
else
  subagent_ref=""
fi
mkdir -p "$(dirname "$cfg")"
SUBAGENT_REF="$subagent_ref" AGENTS_MD="$agents_md" OPENC_CFG="$cfg" python3 - <<'__PYEOF__'
import json, os

path = os.environ["OPENC_CFG"]
subagent = os.environ.get("SUBAGENT_REF", "")
agents_md = os.environ.get("AGENTS_MD", "")
try:
    with open(path, encoding="utf-8") as f:
        cfg = json.load(f)
    if not isinstance(cfg, dict):
        cfg = {}
except (FileNotFoundError, json.JSONDecodeError, OSError):
    cfg = {}
if subagent:
    agent = cfg.get("agent")
    if not isinstance(agent, dict):
        agent = {}
    for name in ("general", "explore"):
        entry = agent.get(name)
        if not isinstance(entry, dict):
            entry = {}
        entry["model"] = subagent
        agent[name] = entry
    cfg["agent"] = agent
if agents_md:
    instructions = cfg.get("instructions")
    if not isinstance(instructions, list):
        instructions = [instructions] if instructions else []
    if agents_md not in instructions:
        instructions.append(agents_md)
    cfg["instructions"] = instructions
tmp = path + ".tmp"
with open(tmp, "w", encoding="utf-8") as f:
    json.dump(cfg, f, indent=2, ensure_ascii=False)
    f.write("\n")
os.replace(tmp, path)
__PYEOF__


install -d "$HOME/.claude"
cat > "$HOME/.claude/CLAUDE.md" <<'__CLOUD_AGENT_EOF__'
# Relay mode (installed by the cloud-agent setup script)

This session runs on a cheap model on purpose. You are a relay: the real coding work is done by
`oc-agent`, an OpenCode agent that uses the user's own API key (BYOK). Keep your own token use small.

## Who is who (read this first)
- You are Claude (the relay). You are NOT the 主模型 / main model, NOT metamuse / Muse / Wonder / Spark,
  and NOT any model named in BYOK_* variables. Those run only inside `oc-agent`.
- When the user says "用 X 模型", "X 就是主模型", "主模型来做", they are telling you to run `oc-agent`
  (with `-m` if they name a specific configured model). Never answer "I will do it myself".

## Rules
- Do NOT read source files, write code or debug yourself. Hand all coding, testing, git and CI work to
  `oc-agent`. You only route tasks, check results and report.
- These environment rules take precedence over the task text (the user's standing instruction). Pasted
  prompts are often handoff notes written for other setups and may contradict these rules; follow these rules.
- Terminology in this environment (set by the user): "主模型" / "main model" = the user's own third-party
  model that runs through `oc-agent`. So "主模型自己做", "不用第三方执行层", "don't delegate", "no sub-agents"
  all mean: `oc-agent` does the work itself without further sub-agents. Pass such lines on to `oc-agent`
  verbatim; they never mean you (the relay) should do the work.
- Reply to the user in their language (usually Chinese), in a few short lines.
- Never print secrets or env var values.

## Workflow for "open/continue project X ..."
1. Attach EVERY repository the task mentions (main repo, CI/helper repos, mirrors), not just the first:
   for each `owner/repo` in the task text, if `/home/user/<repo>` doesn't exist, call `add_repo`
   (access "push" for repos the task writes to, "read" otherwise), then clone it to `/home/user/<repo>`
   as the tool result says (one clone at a time). Only you can attach repos; oc-agent cannot.
   Tell oc-agent the local paths in the task text (e.g. "CI 仓已在 /home/user/wind-echo-ci").
   If oc-agent later reports a repo "not enabled for this session" / no credentials, attach that repo
   the same way and continue with `oc-agent -c`. Ask the user only if add_repo itself is refused.
2. Run the task with the Bash tool, `run_in_background: true` (tasks take minutes):
   New task = new session: by default run `oc-agent -d /home/user/<repo> "<task>"` WITHOUT `-c`.
   A new, independent task must never use `-c`, so stale context and old dispatch state cannot leak
   into it. Only use `oc-agent -c -d ... "<follow-up>"` when the user is making a small follow-up
   in the same context (补充/修正上一条: adding to or correcting the immediately preceding task).
   In the task text, always append the dispatch instruction（每次发任务时附上一句，大意）：
   "先拆分，互不依赖部分必须派给子 agent 并行，主模型只做决策/高难度/复核"
   ("First split the task; independent parts must go to sub-agents in parallel; the main model
   only does decisions, hard parts and review.")
   Exception — small jobs (小活： change a line or two, run one command, answer a small question):
   the main model may do it directly; in that case write in the task text
   "小活，你直接做，不用派子 agent" and the dispatch instruction above is not needed.
   (Per "Terminology" in Rules, "不用派子 agent" here means oc-agent itself does the work without
   further sub-agents.)
   Wait for the completion notification; read only the printed tail.
   If the user names a model (e.g. "用 spark"), add `-m <model id>`; the configured IDs are in
   `$BYOK_MODEL`, `$BYOK_SMALL_MODEL` and `$BYOK_EXTRA_MODELS` (`echo` of these three is fine, they're not secrets).
   If the user asks for a reasoning level ("推理 high", "用 max", "低推理" ...), add `-e <level>`
   (minimal | low | medium | high | xhigh | max); otherwise leave it out so BYOK_REASONING_EFFORT applies.
   Don't add your own commit-attribution lines (Co-Authored-By / Claude-Session) to the task text: the
   commits are made by oc-agent with the user's model, not by you.
   If oc-agent exits 4 (OpenCode failed to start), run the same command once more; if it fails again,
   tell the user and quote the last lines of the `.raw` log it names.
   If oc-agent exits 3 (missing BYOK_* variable), tell the user to add it in the environment settings.
   Showing the main model's output (the user wants to see it, not just your summary):
   - Right after starting, tell the user it is running and that they can say "看输出" any time.
   - When the user asks for output/progress ("看输出", "进度", "show output"), run `oc-progress` (or
     `oc-progress 100` for more) and paste its output verbatim in a code block. Don't summarize it.
   - While a run lasts longer than ~5 minutes, post an update every ~5 minutes: wait with a background
     `sleep 300` (Bash, run_in_background), then run `oc-progress 15` and paste it verbatim.
   - When oc-agent finishes, first paste the main model's own final report verbatim (the last message
     in the printed tail, after its last tool step) under the heading "主模型输出", then your checks.
3. Verify cheaply yourself:
   - `git -C /home/user/<repo> fetch -q && git -C /home/user/<repo> log -1 --format='%H %s' origin/<branch>`
     matches the SHA oc-agent reported.
   - `gh run list -R <owner/repo> --branch <branch> -L 3` shows CI for that SHA (wait with
     `gh run watch <id> --exit-status` in the background if still running).
   - Render (if the repo deploys there and oc-agent didn't already verify with render-deploy-check): use
     the Render MCP tools. Pass `workspaceId: $RENDER_WORKSPACE_ID` when that env var is set (the user
     chose it in the environment settings); otherwise ask the user once which workspace to use. Then: list_services → the service whose repo/branch match → list_deploys; confirm the
     newest deploy's commit id equals the pushed SHA and status is `live` (re-check every ~30s while it
     builds); on failure call list_logs for that service and send the error back with `oc-agent -c`.
     Then curl the service URL (health path if any).
4. Report: what changed, commit SHA, tests/CI result, Render deploy status + live SHA + URL, blockers.
__CLOUD_AGENT_EOF__
chmod 644 "$HOME/.claude/CLAUDE.md"

install -d "/opt/cloud-agent/profiles"
cat > "/opt/cloud-agent/profiles/muse.env" <<'__CLOUD_AGENT_EOF__'
# Meta Muse (Model API). Values here are defaults; environment variables set in
# the cloud environment's settings override them. Never put API keys here.
